import * as THREE from './vendor/three.module.js';

const STATIONS = [
  {id:'tunis',name:'Tunis',country:'Tunisia',code:'TN',cost:0,accent:0xf7a86a},
  {id:'paris',name:'Paris',country:'France',code:'FR',cost:0,accent:0xa5c9ed},
  {id:'rome',name:'Rome',country:'Italy',code:'IT',cost:700,accent:0xeec99b},
  {id:'barcelona',name:'Barcelona',country:'Spain',code:'ES',cost:900,accent:0xf5bca2},
  {id:'berlin',name:'Berlin',country:'Germany',code:'DE',cost:1100,accent:0xbbc9da},
  {id:'istanbul',name:'Istanbul',country:'Türkiye',code:'TR',cost:1300,accent:0xcbb2d6}
];
const city = Object.fromEntries(STATIONS.map(s=>[s.id,s]));
const $ = id=>document.getElementById(id);
const CAPACITY=6, BUS_COST=650, SPAWN_MS=1800, SAVE_KEY='souha-bus-station-stories-v1';
const euro=n=>'€'+Math.floor(n).toLocaleString('en-US');
let currentStation='tunis',selectedBus=1,sheet=null,sound=localStorage.getItem('souha-sound')!=='off';
let game;

function newPassenger(origin,dest,id){return {id,origin,dest};}
function freshGame(){const passengers=[],buses=[];let nextPassenger=1;for(let i=0;i<10;i++)passengers.push(newPassenger('tunis','paris',nextPassenger++));for(let i=0;i<9;i++)passengers.push(newPassenger('paris','tunis',nextPassenger++));for(let id=1;id<=5;id++)buses.push({id,location:id<=3?'tunis':'paris',status:'idle',passengers:0,destination:null,origin:null,departed:0,arrival:0,fare:0});return {version:1,coins:360,moved:0,open:['tunis','paris'],buses,passengers,nextPassenger,nextBus:6,lastSpawn:Date.now()};}
function load(){try{const data=JSON.parse(localStorage.getItem(SAVE_KEY));if(data?.version===1&&Array.isArray(data.buses)&&Array.isArray(data.passengers)&&Array.isArray(data.open))return data;}catch{}return freshGame();}
game=load();
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(game));}
function availableBuses(){return game.buses.filter(b=>b.status==='idle'&&b.location===currentStation).sort((a,b)=>(a.readyAt||0)-(b.readyAt||0)||a.id-b.id);}
function getSelectedBus(){return game.buses.find(b=>b.id===selectedBus&&b.status==='idle'&&b.location===currentStation);}
function syncSelectedBus(){selectedBus=availableBuses()[0]?.id??null;}
function stationQueue(id){return game.passengers.filter(p=>p.origin===id).length;}
function ticketPrice(origin,dest){const a=STATIONS.findIndex(s=>s.id===origin),b=STATIONS.findIndex(s=>s.id===dest);return 65+Math.abs(a-b)*15;}
function tripTime(origin,dest){const a=STATIONS.findIndex(s=>s.id===origin),b=STATIONS.findIndex(s=>s.id===dest);return (8+Math.abs(a-b)*2)*1000;}
function beep(frequency=600){if(!sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(.04,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.17);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.17);osc.onended=()=>ctx.close();}catch{}}
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('toast-stack').appendChild(node);setTimeout(()=>node.remove(),2700);}

function boardPassenger(id){const bus=getSelectedBus(),passenger=game.passengers.find(p=>p.id===id&&p.origin===currentStation);if(!passenger)return;if(!bus)return toast('This station needs a bus. Send one here from another station.',true);if(entryEffects.some(e=>e.id===bus.id))return toast('The next coach is pulling into the bay!');if(bus.passengers>=CAPACITY)return toast('This bus is full! Tap it to start the trip.');if(bus.destination&&bus.destination!==passenger.dest)return toast(`Bus #${String(bus.id).padStart(2,'0')} is boarding for ${city[bus.destination].name}. Wait for the next bus for this traveler.`,true);bus.destination=passenger.dest;bus.passengers++;game.passengers=game.passengers.filter(p=>p.id!==id);save();renderDynamic();renderHUD();beep(bus.passengers===CAPACITY?880:650);}
function tapBus(id){const bus=game.buses.find(b=>b.id===id);if(!bus||bus.status!=='idle'||bus.location!==currentStation)return;if(id!==selectedBus)return toast(`Bus #${String(id).padStart(2,'0')} is waiting. Fill the coach in the departure bay first.`);if(entryEffects.some(e=>e.id===id))return toast('The coach is pulling into the bay!');if(bus.passengers===CAPACITY)return departBus(bus);toast(bus.passengers?`${bus.passengers} of ${CAPACITY} travelers aboard. Keep boarding!`:'Tap waiting travelers to board this coach.');beep(490);}
function departBus(bus){if(bus.passengers<CAPACITY)return toast('Fill the bus before starting the trip.',true);const next=availableBuses().find(b=>b.id!==bus.id);pendingMoves=next?{[next.id]:{x:-6.2,z:0}}:null;launchVisualDeparture(bus.id);bus.origin=bus.location;bus.departed=Date.now();bus.arrival=bus.departed+tripTime(bus.origin,bus.destination);bus.fare=ticketPrice(bus.origin,bus.destination);bus.status='trip';selectedBus=next?.id??null;save();renderDynamic();renderHUD();toast(`Bus #${String(bus.id).padStart(2,'0')} is off to ${city[bus.destination].name}!`);beep(980);}
function tick(){let changed=false;const now=Date.now();for(const bus of game.buses){if(bus.status==='trip'&&now>=bus.arrival){const earnings=bus.fare*bus.passengers;game.coins+=earnings;game.moved+=bus.passengers;bus.location=bus.destination;bus.status='idle';bus.readyAt=now;bus.origin=null;bus.destination=null;bus.passengers=0;bus.departed=0;bus.arrival=0;bus.fare=0;changed=true;toast(`Bus #${String(bus.id).padStart(2,'0')} arrived! +${euro(earnings)}`);beep(1010);}}
  if(now-game.lastSpawn>=SPAWN_MS){const turns=Math.min(24,Math.floor((now-game.lastSpawn)/SPAWN_MS));for(let i=0;i<turns;i++){const origin=game.open[Math.floor(Math.random()*game.open.length)],destinations=game.open.filter(id=>id!==origin),dest=destinations[Math.floor(Math.random()*destinations.length)];if(stationQueue(origin)<24){game.passengers.push(newPassenger(origin,dest,game.nextPassenger++));changed=true;}}game.lastSpawn=now;}
  if(changed){save();if(!entryEffects.length)renderDynamic();renderHUD();if(sheet)renderSheet();}else if(sheet==='fleet')renderSheet();}
function switchStation(id){if(!game.open.includes(id))return;currentStation=id;syncSelectedBus();closeSheet();buildStatic();renderDynamic();renderHUD();beep(560);}
function buyStation(id){const target=city[id];if(!target||game.open.includes(id))return;if(game.coins<target.cost)return toast(`Earn ${euro(target.cost-game.coins)} more to open ${target.name}.`,true);game.coins-=target.cost;game.open.push(id);const destinations=game.open.filter(x=>x!==id);for(let i=0;i<7;i++)game.passengers.push(newPassenger(id,destinations[i%destinations.length],game.nextPassenger++));for(const origin of destinations){const arrivals=[];for(let i=0;i<(origin===currentStation?6:2);i++)arrivals.push(newPassenger(origin,id,game.nextPassenger++));if(origin===currentStation)game.passengers.unshift(...arrivals);else game.passengers.push(...arrivals);}save();toast(`${target.name} station is open!`);switchStation(id);beep(900);}
function buyBus(){if(game.coins<BUS_COST)return toast(`Earn ${euro(BUS_COST-game.coins)} more for a bus.`,true);game.coins-=BUS_COST;const id=game.nextBus++;game.buses.push({id,location:currentStation,status:'idle',passengers:0,destination:null,origin:null,departed:0,arrival:0,fare:0,readyAt:Date.now()});save();closeSheet();renderDynamic();renderHUD();toast(`New Souha Bus #${String(id).padStart(2,'0')} joined the queue at ${city[currentStation].name}!`);beep(870);}

function renderHUD(){syncSelectedBus();$('coins').textContent=game.coins.toLocaleString('en-US');$('moved').textContent=game.moved.toLocaleString('en-US');$('station-flag').textContent=city[currentStation].code;$('station-name').textContent=city[currentStation].name+' Station';const bus=getSelectedBus();$('selected-bus-name').textContent=bus?`Souha Bus #${String(bus.id).padStart(2,'0')}`:'No bus at this station';const badge=$('bus-pill');badge.className='bus-pill'+(!bus?' none':bus.passengers===CAPACITY?' full':'');badge.textContent=!bus?'WAITING FOR BUS':bus.passengers===CAPACITY?'FULL · READY TO GO':'READY TO BOARD';$('route-line').textContent=!bus?'Send a bus here or buy one in My buses.':bus.destination?`${city[currentStation].code} ${city[currentStation].name}  →  ${city[bus.destination].code} ${city[bus.destination].name} · ${euro(ticketPrice(currentStation,bus.destination))}/traveler`:'Pick up travelers to choose a destination';$('load-fill').style.width=`${(bus?.passengers||0)/CAPACITY*100}%`;$('passenger-count').textContent=`${bus?.passengers||0} / ${CAPACITY} aboard`;$('bus-instruction').textContent=!bus?'Select another station or buy a bus here.':bus.passengers===CAPACITY?'Tap the orange bus in the station to start the trip!':`Tap ${CAPACITY-bus.passengers} more traveler${CAPACITY-bus.passengers===1?'':'s'} to fill this bus.`;$('scene-hint').textContent=!bus?'Choose a station with a bus to start boarding':bus.passengers===CAPACITY?'Bus is full! Tap the bus to depart':`Tap a traveler to board Bus #${String(bus.id).padStart(2,'0')}`;}
function openSheet(kind){sheet=kind;$('modal-backdrop').classList.remove('hidden');renderSheet();}
function closeSheet(){sheet=null;$('modal-backdrop').classList.add('hidden');}
function renderSheet(){if(!sheet)return;const eyebrow=$('sheet-eyebrow'),title=$('sheet-title'),content=$('sheet-content');if(sheet==='stations'){eyebrow.textContent='HOP BETWEEN TERMINALS';title.textContent='Your stations';content.innerHTML=`<p class="sheet-intro">Visit another station to board its waiting travelers.</p><div class="sheet-list">${game.open.map(id=>`<button class="sheet-row ${id===currentStation?'selected':''}" data-station="${id}"><span class="sheet-row-icon">${city[id].code}</span><span><b>${city[id].name}</b><small>${city[id].country} · ${stationQueue(id)} waiting</small></span><span class="sheet-row-end">${id===currentStation?'HERE':'VISIT →'}</span></button>`).join('')}</div><div class="sheet-note">Travelers keep arriving while you play.</div>`;}
  else if(sheet==='fleet'){eyebrow.textContent='YOUR ORANGE FLEET';title.textContent=`${game.buses.length} Souha Buses`;content.innerHTML=`<p class="sheet-intro">The first available coach boards in the departure bay. Tap a full coach in the scene to send it off; the next pulls in right away.</p><div class="sheet-list">${game.buses.map(bus=>{const trip=bus.status==='trip',place=trip?`${city[bus.origin].name} → ${city[bus.destination].name}`:`At ${city[bus.location].name}`,detail=trip?`${Math.max(0,Math.ceil((bus.arrival-Date.now())/1000))}s to arrival`:`${bus.passengers}/${CAPACITY} travelers aboard`;return `<button class="sheet-row ${bus.id===selectedBus?'selected':''}" data-fleet-bus="${bus.id}"><span class="sheet-row-icon">▰</span><span><b>Souha Bus #${String(bus.id).padStart(2,'0')}</b><small>${place} · ${detail}</small></span><span class="sheet-row-end ${trip?'status-trip':'status-idle'}">${trip?'ON TRIP':'READY'}</span></button>`}).join('')}</div><div class="buy-section"><h3>Add a bus at ${city[currentStation].name}</h3><p>One orange bus for ${CAPACITY} travelers. Your new vehicle starts at this station.</p><button id="buy-bus" ${game.coins<BUS_COST?'disabled':''}>Buy Souha Bus · ${euro(BUS_COST)}</button></div>`;}
  else{eyebrow.textContent='MORE PLACES TO EXPLORE';title.textContent='Open a station';const locked=STATIONS.filter(s=>!game.open.includes(s.id));content.innerHTML=`<p class="sheet-intro">Add another country to your network. New travelers will start waiting there immediately.</p><div class="sheet-list">${locked.length?locked.map(s=>`<div class="sheet-row"><span class="sheet-row-icon">${s.code}</span><span><b>${s.name}</b><small>${s.country}</small></span><button class="sheet-row-end build-action" data-build="${s.id}" ${game.coins<s.cost?'disabled':''}>${euro(s.cost)} ＋</button></div>`).join(''):'<p class="sheet-intro">Every station is open. Your network spans the whole world!</p>'}</div><div class="sheet-note">Earn fares when full buses reach their destination.</div>`;}}

// A small low-poly station fills the screen. The scene changes when the player changes stations.
const scene=new THREE.Scene();scene.background=new THREE.Color(0xbbe3e5);scene.fog=new THREE.Fog(0xbbe3e5,16,34);
const canvas=$('scene'),renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;
const camera=new THREE.OrthographicCamera(-4,4,5,-5,.1,70);camera.position.set(2.8,8.4,10);camera.lookAt(0,.15,.25);
scene.add(new THREE.HemisphereLight(0xffffff,0x93bfa3,2.1));const sunlight=new THREE.DirectionalLight(0xfff0cc,2.2);sunlight.position.set(-4,11,6);sunlight.castShadow=true;sunlight.shadow.mapSize.set(1024,1024);sunlight.shadow.camera.left=-9;sunlight.shadow.camera.right=9;sunlight.shadow.camera.top=9;sunlight.shadow.camera.bottom=-9;sunlight.shadow.normalBias=.025;scene.add(sunlight);
const staticGroup=new THREE.Group(),dynamicGroup=new THREE.Group(),departureEffects=[],entryEffects=[],smokeEffects=[];let pendingMoves=null;scene.add(staticGroup,dynamicGroup);
const material=(color,more={})=>new THREE.MeshLambertMaterial({color,flatShading:true,...more});
const mats={grass:material(0x9bd49e),grass2:material(0xb7dca5),platform:material(0xf7eacb),tile:material(0xfff4df),road:material(0x80a9a6),stripe:material(0xfff5dc),orange:material(0xf7863e),orangeDark:material(0xdd6d2c),cream:material(0xfffaf0),glass:material(0x6fb7bc),dark:material(0x405b5e),wheel:material(0x344347),wheelHub:material(0xdfd8c4),trunk:material(0x997c56),leaf:material(0x71b885),leaf2:material(0x84c99a),skin:material(0xf3c29f),hair:material(0x624d3c)};
function put(group,geometry,mat,x=0,y=0,z=0){const m=new THREE.Mesh(geometry,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
function box(group,w,h,d,mat,x,y,z){return put(group,new THREE.BoxGeometry(w,h,d),mat,x,y,z);}
function clear(group){for(const child of [...group.children]){group.remove(child);child.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&!Object.values(mats).includes(o.material)&&!Array.isArray(o.material))o.material.dispose();});}}
function launchVisualDeparture(id){const model=dynamicGroup.children.find(child=>child.userData.pick?.kind==='bus'&&child.userData.pick.id===id);if(!model)return;for(const child of [...model.children])if(child.userData.selectionRing){model.remove(child);child.geometry.dispose();child.material.dispose();}dynamicGroup.remove(model);scene.add(model);departureEffects.push({model,started:performance.now(),x:model.position.x,lastSmoke:0});}
function emitSmoke(model,now){for(let i=0;i<3;i++){const p=model.localToWorld(new THREE.Vector3((i-1)*.35,.3,-1.35));const puff=new THREE.Mesh(new THREE.IcosahedronGeometry(.17+Math.random()*.07,0),new THREE.MeshBasicMaterial({color:0xe5e9df,transparent:true,opacity:.72,depthWrite:false}));puff.position.copy(p);scene.add(puff);smokeEffects.push({puff,started:now,vx:(Math.random()-.5)*.5});}}
function tree(group,x,z,s=1){put(group,new THREE.CylinderGeometry(.1*s,.15*s,.78*s,6),mats.trunk,x,.4*s,z);put(group,new THREE.IcosahedronGeometry(.58*s,0),Math.random()>.5?mats.leaf:mats.leaf2,x,1.18*s,z);}
function textTexture(text,color='#416358',background='#fff6e5'){const el=document.createElement('canvas');el.width=768;el.height=140;const cx=el.getContext('2d');cx.fillStyle=background;cx.fillRect(0,0,768,140);cx.fillStyle=color;cx.textAlign='center';cx.textBaseline='middle';cx.font='bold 76px Arial';cx.fillText(text,384,75);const texture=new THREE.CanvasTexture(el);texture.colorSpace=THREE.SRGBColorSpace;return texture;}
function terminalSign(text){const texture=textTexture(text,'#496452','#fff4d7');const sign=put(staticGroup,new THREE.PlaneGeometry(3.5,.5),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide}),0,1.36,-2.86);sign.castShadow=false;return sign;}
function buildStatic(){
  clear(staticGroup);const s=city[currentStation];scene.background=new THREE.Color(currentStation==='paris'?0xc6e6ed:0xbbe3e5);
  const ground=put(staticGroup,new THREE.PlaneGeometry(100,100),mats.grass,0,-.13,0);ground.rotation.x=-Math.PI/2;ground.castShadow=false;
  // The paved road continues beyond the visible screen so departing coaches stay grounded.
  box(staticGroup,15.4,.25,9.3,mats.platform,0,-.08,.35);
  box(staticGroup,15.1,.025,3.72,mats.road,0,.065,0);
  for(const z of [-1.82,1.82])box(staticGroup,14.8,.014,.06,mats.stripe,0,.091,z);
  for(const z of [-.61,.61])for(let x=-6.75;x<=6.75;x+=1.5)box(staticGroup,.75,.014,.045,mats.stripe,x,.091,z);
  // A loading bay marks the middle of three parallel travel lanes.
  for(const x of [-1.7,1.7])box(staticGroup,.075,.014,1.05,mats.stripe,x,.093,0);
  for(const x of [-5.1,5.1])box(staticGroup,.07,.014,1.0,mats.stripe,x,.093,0);
  box(staticGroup,7.1,1.54,.85,mats.cream,0,.9,-3.35);
  box(staticGroup,7.4,.17,1.1,material(s.accent),0,1.75,-3.35);
  box(staticGroup,.9,1.02,.03,mats.glass,0,.66,-2.90);
  for(const x of [-2.65,-1.55,1.55,2.65])box(staticGroup,.72,.68,.03,mats.glass,x,.9,-2.90);
  const sign=terminalSign(`SOUHA BUS · ${s.name.toUpperCase()}`);sign.position.z=-2.86;
  for(const x of [-6.8,6.8])for(const z of [-3.5,3.85])tree(staticGroup,x,z,.92+Math.random()*.14);
  for(const x of [-5.7,5.7]){put(staticGroup,new THREE.CylinderGeometry(.21,.24,.32,6),mats.cream,x,.16,3.95);put(staticGroup,new THREE.IcosahedronGeometry(.35,0),mats.leaf2,x,.52,3.95);}
  for(let i=0;i<18;i++){const x=-7.2+Math.random()*14.4,z=-4+Math.random()*8.5;if(Math.abs(x)<4&&z>-2.5&&z<3.7)continue;const flower=put(staticGroup,new THREE.IcosahedronGeometry(.05,0),material(i%2?0xffd694:0xffffff),x,.13,z);flower.castShadow=false;}
}
const busTexture=textTexture('Souha Bus','#bd5a28','#fff9e9');
function sideBrandTexture(){const el=document.createElement('canvas');el.width=768;el.height=160;const ctx=el.getContext('2d');ctx.clearRect(0,0,768,160);ctx.fillStyle='#fff8e9';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 112px Arial';ctx.fillText('Souha Bus',384,83);const texture=new THREE.CanvasTexture(el);texture.colorSpace=THREE.SRGBColorSpace;return texture;}
const sideBrand=sideBrandTexture();
function buildBus(bus,x,z){
  const g=new THREE.Group();g.position.set(x,.09,z);g.rotation.y=Math.PI/2;g.userData.pick={kind:'bus',id:bus.id};dynamicGroup.add(g);
  // Long touring coach body: broad orange flanks, raised passenger cabin and a sloped-looking front.
  box(g,.95,.28,2.34,mats.orangeDark,0,.29,0);
  box(g,.98,.75,2.28,mats.orange,0,.67,-.02);
  box(g,.96,.64,.34,mats.orange,0,.69,1.12);
  box(g,.98,.08,2.30,mats.orangeDark,0,1.08,-.01);
  box(g,.77,.45,.025,mats.glass,0,.85,1.305);
  box(g,.82,.07,.035,mats.dark,0,1.08,1.31);
  box(g,.88,.1,.06,mats.cream,0,.38,1.32);
  for(const side of [-1,1]){
    const xx=side*.5;
    box(g,.025,.32,1.68,mats.glass,xx,.88,-.27);
    for(const zz of [-.92,-.54,-.16,.22,.58])box(g,.04,.35,.035,mats.orangeDark,xx+side*.01,.88,zz);
    box(g,.03,.04,1.75,mats.dark,xx+side*.01,.7,-.27);
    box(g,.03,.025,1.6,mats.orangeDark,xx+side*.01,.39,-.29);
    const brand=put(g,new THREE.PlaneGeometry(1.74,.36),new THREE.MeshBasicMaterial({map:sideBrand,transparent:true,side:THREE.DoubleSide,depthWrite:false}),side*.524,.52,-.22);
    brand.rotation.y=side*Math.PI/2;brand.castShadow=false;
    for(const zz of [-.88,-.48,.82]){
      const wheel=put(g,new THREE.CylinderGeometry(.19,.19,.08,12),mats.wheel,side*.55,.19,zz);wheel.rotation.z=Math.PI/2;
      const hub=put(g,new THREE.CylinderGeometry(.075,.075,.083,12),mats.wheelHub,side*.55,.19,zz);hub.rotation.z=Math.PI/2;
    }
    box(g,.11,.1,.13,mats.dark,side*.57,.96,1.03);
  }
  for(const xx of [-.34,.34])box(g,.14,.12,.035,mats.cream,xx,.52,1.33);
  box(g,.35,.06,.5,mats.cream,0,1.15,-.45);
  const frontBrand=put(g,new THREE.PlaneGeometry(.67,.16),new THREE.MeshBasicMaterial({map:busTexture,side:THREE.DoubleSide}),0,.39,1.35);frontBrand.castShadow=false;
  if(bus.id===selectedBus){const ring=put(g,new THREE.TorusGeometry(1.17,.055,5,38),material(0xffa358),0,.06,0);ring.rotation.x=-Math.PI/2;ring.scale.y=1.19;ring.castShadow=false;ring.userData.selectionRing=true;}
  const hit=put(g,new THREE.BoxGeometry(1.24,1.35,2.52),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}),0,.64,0);hit.castShadow=false;hit.receiveShadow=false;
  return g;
}
const shirtColors=[0xf6a776,0x82b8d2,0xc8a7d8,0x8fc398,0xf0cb75,0xd8a28c];
function buildPerson(passenger,x,z,index){const g=new THREE.Group();g.position.set(x,.1,z);g.scale.setScalar(.8);g.userData.pick={kind:'passenger',id:passenger.id};dynamicGroup.add(g);put(g,new THREE.CylinderGeometry(.11,.16,.33,6),material(shirtColors[index%shirtColors.length]),0,.3,0);put(g,new THREE.IcosahedronGeometry(.14,0),mats.skin,0,.61,0);put(g,new THREE.IcosahedronGeometry(.145,0),mats.hair,0,.69,-.045);for(const xx of [-.075,.075])put(g,new THREE.CylinderGeometry(.035,.04,.18,5),mats.dark,xx,.08,0);const hit=put(g,new THREE.CylinderGeometry(.3,.3,.92,8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}),0,.42,0);hit.castShadow=false;hit.receiveShadow=false;return g;}
let labels=[];function renderDynamic(){syncSelectedBus();clear(dynamicGroup);labels=[];const visible=availableBuses().slice(0,1),bays=[[0,0]];
  for(let i=0;i<visible.length;i++){const bus=visible[i],[x,z]=bays[i],g=buildBus(bus,x,z),origin=pendingMoves?.[bus.id];if(origin&&Math.hypot(origin.x-x,origin.z-z)>.1){g.position.set(origin.x,.09,origin.z);entryEffects.push({id:bus.id,model:g,started:performance.now()+180,fromX:origin.x,fromZ:origin.z,toX:x,toZ:z});}labels.push({kind:'bus',id:bus.id,object:g,anchor:new THREE.Vector3(0,1.49,-.15),text:i===0?bus.passengers===CAPACITY?'GO!':`${bus.passengers}/${CAPACITY}`:'WAIT'});}pendingMoves=null;
  const passengers=game.passengers.filter(p=>p.origin===currentStation).slice(0,6);for(let i=0;i<passengers.length;i++){const col=i%3,row=Math.floor(i/3),x=(col-1)*1.42,z=2.7+row*.62,g=buildPerson(passengers[i],x,z,i);labels.push({kind:'passenger',id:passengers[i].id,object:g,anchor:new THREE.Vector3(0,.96,0),text:city[passengers[i].dest].code});}
  renderLabels();}
function renderLabels(){const host=$('scene-labels'),bus=getSelectedBus();host.innerHTML=labels.map(entry=>{if(entry.kind==='bus'){const b=game.buses.find(x=>x.id===entry.id);return `<button class="bus-tag ${entry.id===selectedBus?'selected':''} ${b.passengers===CAPACITY?'full':''}" data-bus="${entry.id}" aria-label="Bus ${entry.id}, ${b.passengers} of ${CAPACITY} travelers aboard">${entry.text}</button>`;}const p=game.passengers.find(x=>x.id===entry.id);return `<button class="passenger-tag ${bus?.destination&&bus.destination!==p?.dest?'mismatch':''}" data-passenger="${entry.id}" aria-label="Board passenger for ${city[p.dest].name}">${entry.text} →</button>`}).join('');positionLabels();}
function positionLabels(){const r=canvas.getBoundingClientRect();for(const entry of labels){const el=$('scene-labels').querySelector(`[data-${entry.kind==='bus'?'bus':'passenger'}="${entry.id}"]`);if(!el)continue;const p=entry.object.localToWorld(entry.anchor.clone()).project(camera);let x=(p.x*.5+.5)*r.width,y=(-p.y*.5+.5)*r.height;const half=el.offsetWidth/2;x=THREE.MathUtils.clamp(x,half+5,r.width-half-5);y=THREE.MathUtils.clamp(y,el.offsetHeight+8,r.height-5);el.style.left=x+'px';el.style.top=y+'px';el.style.display=p.z>1?'none':'';}}
function resize(){const w=innerWidth,h=innerHeight,aspect=w/h,halfW=aspect<1?4.05:Math.min(8.2,aspect*4.5);renderer.setSize(w,h,false);camera.left=-halfW;camera.right=halfW;camera.top=halfW/aspect;camera.bottom=-halfW/aspect;camera.updateProjectionMatrix();positionLabels();}addEventListener('resize',resize);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down=null;canvas.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>12){down=null;return;}down=null;const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(dynamicGroup.children,true);for(const hit of hits){let o=hit.object;while(o&&!o.userData.pick)o=o.parent;if(o?.userData.pick){const {kind,id}=o.userData.pick;kind==='bus'?tapBus(id):boardPassenger(id);break;}}});
$('scene-labels').addEventListener('click',e=>{const passenger=e.target.closest('[data-passenger]'),bus=e.target.closest('[data-bus]');if(passenger)boardPassenger(Number(passenger.dataset.passenger));else if(bus)tapBus(Number(bus.dataset.bus));});$('station-switch').addEventListener('click',()=>openSheet('stations'));$('stations-button').addEventListener('click',()=>openSheet('stations'));$('fleet-button').addEventListener('click',()=>openSheet('fleet'));$('build-button').addEventListener('click',()=>openSheet('build'));$('close-sheet').addEventListener('click',closeSheet);$('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeSheet();const station=e.target.closest('[data-station]'),build=e.target.closest('[data-build]'),fleet=e.target.closest('[data-fleet-bus]');if(station)switchStation(station.dataset.station);else if(build)buyStation(build.dataset.build);else if(fleet){const bus=game.buses.find(b=>b.id===Number(fleet.dataset.fleetBus));if(bus.status==='trip')return toast(`Bus #${String(bus.id).padStart(2,'0')} is still traveling.`);currentStation=bus.location;selectedBus=bus.id;closeSheet();buildStatic();renderDynamic();renderHUD();}else if(e.target.id==='buy-bus')buyBus();});addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();});$('sound').addEventListener('click',()=>{sound=!sound;localStorage.setItem('souha-sound',sound?'on':'off');$('sound').textContent=sound?'♫':'♩';toast(sound?'Sound on':'Sound off');});
function animate(){requestAnimationFrame(animate);const now=performance.now();for(let i=departureEffects.length-1;i>=0;i--){const effect=departureEffects[i],t=Math.min(1,(now-effect.started)/650),ease=1-(1-t)**3;effect.model.position.x=effect.x+ease*6.2;effect.model.position.y=.09;if(now-effect.lastSmoke>45&&t<.85){emitSmoke(effect.model,now);effect.lastSmoke=now;}if(t>=1){scene.remove(effect.model);effect.model.traverse(o=>{if(o.geometry)o.geometry.dispose();});departureEffects.splice(i,1);}}
  let entriesFinished=false;for(let i=entryEffects.length-1;i>=0;i--){const effect=entryEffects[i],t=THREE.MathUtils.clamp((now-effect.started)/950,0,1),ease=t*t*(3-2*t);effect.model.position.x=THREE.MathUtils.lerp(effect.fromX,effect.toX,ease);effect.model.position.z=THREE.MathUtils.lerp(effect.fromZ,effect.toZ,ease);effect.model.position.y=.09;if(t>=1){entryEffects.splice(i,1);entriesFinished=true;}}if(entriesFinished&&!entryEffects.length)renderDynamic();
  for(let i=smokeEffects.length-1;i>=0;i--){const effect=smokeEffects[i],t=Math.min(1,(now-effect.started)/620);effect.puff.position.y+=.006;effect.puff.position.x+=effect.vx*.016;effect.puff.scale.setScalar(1+t*2.5);effect.puff.material.opacity=.82*(1-t);if(t>=1){scene.remove(effect.puff);effect.puff.geometry.dispose();effect.puff.material.dispose();smokeEffects.splice(i,1);}}
  positionLabels();renderer.render(scene,camera);}tick();syncSelectedBus();buildStatic();renderDynamic();renderHUD();resize();animate();setInterval(tick,1000);
